{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined city.",
      "visual_description": "A windswept hill overlooks a broken skyline of toppled spires; Mara spreads a torn map across a stone, brass compass spinning.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a long night ahead.",
      "visual_description": "A battered oil lamp held aloft, its single flame-eye glowing amber against twilight clouds, beside Mara's ink-stained coat.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox sniffs the wind at the castle gates.",
      "visual_description": "Massive iron gates hang crooked; a small clockwork fox with blue glass eyes crouches in rubble, its key-wind tail ticking.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver slips through a shattered window.",
      "visual_description": "A figure in a clear diving helmet emerges from a tall broken window as if surfacing from water, coat reflecting flickering city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Mara marks the cursed tower on her map.",
      "visual_description": "A leaning tower wreathed in violet mist; Mara's gloved hand circles it in red ink, the tin fox peeking over her shoulder.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The oracle lamp whispers about the rumored beast in the sky.",
      "visual_description": "Clouds roll low over the cracked rooftops; the lamp's flame stretches into the shape of wide wings, casting long shadows.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Faded royal banners hang above empty streets.",
      "visual_description": "Tattered crimson and gold banners sway over a deserted avenue; the glass diver walks beneath them, his reflection rippling on wet cobbles.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox finds the sleeping tax collector slumped in a booth.",
      "visual_description": "A toll booth with peeling paint; an official snores on a ledger pillow, stamped papers stuck to his sleeves, while the tin fox tugs at his hem.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "Mara tries to question him, but he only mumbles.",
      "visual_description": "Mara crouches with her compass swinging while the tax collector dozes upright, drool on a tax stamp, lamp glowing impatiently beside her.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrols march past in lockstep.",
      "visual_description": "Through a chink in a wall, lines of empty enchanted armor clatter down a torchlit street; the tin fox flattens itself in shadow.",
      "characters": ["tin_guess_placeholder"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver dives into a tall mirror.",
      "visual_description": "A gilded full-length mirror ripples like a pond as the diving-helmeted rescuer plunges in, broken city lights swirling across his coat.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "He surfaces inside a sealed magic door chamber.",
      "visual_description": "An octagonal stone room with a glowing rune-carved door; the glass diver climbs out of a small wall mirror, dripping silver light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp reads the door's riddle.",
      "visual_description": "The lamp hovers near pulsing runes, its single eye narrowed; Mara stands behind it tracing letters with her compass needle.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The tin fox squeezes through a hidden vent.",
      "visual_description": "A narrow grated vent low on the wall; the clockwork fox slips through, tail-key glinting, leaving tiny oil pawprints behind.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "They find Mara's lost partner asleep under a spell.",
      "visual_description": "In a dim chamber lit by the lamp, the sleeping tax collector lies sprawled on a velvet dais, snoring beneath a slow rain of glowing dust.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver carries him out through a window pool.",
      "visual_description": "A tall arched window rippling like water; the diver wades in carrying the slumbering official over one shoulder, papers fluttering free.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The tin fox leads the way across the cracked bridge.",
      "visual_description": "A long stone bridge over a chasm of fog; the clockwork fox sprints ahead, blue eyes blazing, lantern-lit figures hurrying behind.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Beyond the city, Mara folds her map with a tired smile.",
      "visual_description": "Dawn breaks over distant hills; Mara closes her ink-stained map, the lamp dim and content, the tin fox curled at her boot, the diver gazing back at the ruined skyline.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

